package dev.pro8.homeview.direct;
import android.app.*;import android.os.*;import android.content.Intent;import android.widget.TextView;import org.json.JSONObject;
/** ADB-only provisioning activity; the manifest requires the caller's DUMP permission. */
public final class SetupActivity extends Activity {
 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);TextView text=new TextView(this);text.setText("正在应用电脑端配置…");text.setTextSize(24);text.setGravity(android.view.Gravity.CENTER);setContentView(text);String name=getIntent().getStringExtra("setup_name");try{JSONObject config=SetupImport.validate(SetupImport.read(SetupImport.source(this,name)));SetupImport.stage(this,name,config);Intent launch=HomeActivity.homeIntent(this);PendingIntent intent=PendingIntent.getActivity(this,1681,launch,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)getSystemService(ALARM_SERVICE)).setExact(AlarmManager.ELAPSED_REALTIME_WAKEUP,SystemClock.elapsedRealtime()+750,intent);finish();new Handler(Looper.getMainLooper()).postDelayed(()->android.os.Process.killProcess(android.os.Process.myPid()),150);}catch(Exception e){try{SetupImport.result(this,name,"error","配置文件无效，请在电脑端重新开始");}catch(Exception ignored){}text.setText("配置未完成，请在电脑端重试");text.postDelayed(()->finish(),1500);}}
}
